"""«Bugalter» duty: who is reminded the day before a worker's pay day. Today that is
Maftuna (a manager) — marked here when exactly one active member is called so;
otherwise set it in Moliya → Sozlamalar."""

from django.db import migrations, models


def mark_maftuna(apps, schema_editor):
    TelegramMember = apps.get_model("oauth", "TelegramMember")
    found = list(
        TelegramMember.objects.filter(name__iregex=r"maftuna|мафтуна", role__in=["admin", "staff"])
    )
    if len(found) == 1:
        found[0].is_accountant = True
        found[0].save(update_fields=["is_accountant"])
        print(f"  Bugalter: {found[0].name}")


